import {articles,systems,categories,checks,manual} from './data.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const byId=new Map(articles.map(a=>[a.id,a]));
const paths={
 bike:'<circle cx="5" cy="17" r="4"/><circle cx="19" cy="17" r="4"/><path d="M5 17 8 7h4l3 10M8 7 6 4H3m8 13H5m10-6h4l-2-6h-3"/>',
 engine:'<path d="M7 5h8v3h4v4h3v7h-7v2H7v-3H4V9h3V5ZM9 2h4M2 11v5"/>',
 battery:'<rect x="2" y="6" width="18" height="13" rx="2"/><path d="M20 10h2v5h-2M6 3v3m9-3v3M5 12h5m-2.5-2.5v5M13 12h4"/>',
 light:'<path d="M13 5c-7 0-10 3-10 7s3 7 10 7V5ZM17 6l5-2m-5 6 5-1m-5 5 5 1m-5 3 5 2"/>',
 gauge:'<path d="M3 18a10 10 0 1 1 18 0H3Z"/><path d="m12 14 5-5M5 11h2m11 0h2M7 6l1 2m4-4v2"/><circle cx="12" cy="14" r="1.5"/>',
 drive:'<circle cx="6" cy="12" r="4"/><circle cx="18" cy="12" r="3"/><path d="m6 8 12 1M6 16l12-1"/>',
 wheel:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="3"/><path d="M12 3v6m0 6v6M3 12h6m6 0h6M6 6l4 4m4 4 4 4m0-12-4 4m-4 4-4 4"/>',
 seat:'<path d="M3 12h17l1 4H3v-4ZM5 12l1-6h7l3 6M4 19h16m-13-3-1 3m11-3 1 3"/>',
 oil:'<path d="m4 9 10-3 4 11-11 4L4 9ZM9 7 8 3h4l2 3M3 10H1v5h4m14-5 3-1v6h-3"/>',
 filter:'<path d="m3 5 9-3 9 3v14l-9 3-9-3V5Zm0 0 9 3 9-3M12 8v14M6 8v9m3-8v9m6-9v9m3-10v9"/>',
 spark:'<path d="m13 2-2 7h5l-5 8 1-6H7l6-9ZM8 17l-3 4m12-4 2 3M4 9H1m19 0h3"/>',
 fuse:'<rect x="4" y="6" width="16" height="12" rx="2"/><path d="M8 2v4m8-4v4M8 18v4m8-4v4M8 12h2l1-3 2 6 1-3h2"/>',
 turn:'<path d="m14 3 8 8-8 8v-5H3V8h11V3Z"/>',
 coolant:'<path d="M9 14V4a3 3 0 0 1 6 0v10a5 5 0 1 1-6 0ZM12 8v9m6-12h3m-3 5h3"/>',
 brake:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="2"/><path d="M18 3h4v8h-4M7 7l1 1m8 8 1 1m-10 0 1-1m8-8 1-1"/>',
 suspension:'<path d="m10 2 4 3-5 3 6 3-6 3 6 3-5 3 4 2M10 2h4m-4 20h4"/>',
 box:'<path d="m3 6 9-4 9 4v13l-9 3-9-3V6Zm0 0 9 4 9-4M12 10v12M7 4l9 4v5"/>',
 fuel:'<path d="M4 21V4h10v17M2 21h14M6 6h6v5H6V6Zm8 6h3v6a2 2 0 0 0 4 0V8l-3-3m3 6h-3V8"/>',
 tool:'<path d="M15 3a6 6 0 0 0-7 8L2 17a3 3 0 0 0 5 5l7-7a6 6 0 0 0 7-8l-4 4-4-4 4-4h-2Z"/>'
};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.tool}</svg>`;}
function specs(rows){return `<div class="spec-list">${rows.map(([k,v])=>`<div class="spec-row"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div>`;}
function table(t){return `<div class="table-scroll"><table><thead><tr>${t.head.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${t.rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
let viewer,activeSystem='overview',activeArticle=null,filter='Все узлы',search='',toastTimer,dialogTrigger=null;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function renderSystems(){$('#systemNav').innerHTML=systems.map(s=>`<button class="system-button ${s.id===activeSystem?'active':''}" data-system="${s.id}" aria-pressed="${s.id===activeSystem}">${icon(s.icon)}<span>${s.title}</span><span>${s.tag}</span></button>`).join('');$('#systemCount').textContent=String(systems.length).padStart(2,'0');}
const opening={seat:['seat','Открыть сиденье','Закрыть сиденье'],glove:['glove','Открыть бардачок','Закрыть бардачок'],battery:['battery','Снять переднюю панель','Вернуть переднюю панель'],engine:['engine','Открыть доступ к мотору','Собрать кузов']};
function openButton(id){const entry=opening[id];if(!entry)return '';const state=viewer?.isOpen(entry[0]);return `<button class="outline-button panel-open" data-toggle-part="${entry[0]}" aria-pressed="${!!state}" ${viewer?'':'disabled'}>${entry[state?2:1]}<span aria-hidden="true">↗</span></button>`;}
function renderDetail(){
 const panel=$('#detailContent');
 if(!activeArticle){panel.innerHTML=`<div class="detail-kicker"><span>ТВОЙ ЛИЧНЫЙ ГАРАЖ</span><span>2009 / VN</span></div><h2>Знакомый байк.<br>Больше деталей.</h2><p class="detail-description">Нажми на точку модели, чтобы узнать, что внутри и как это обслуживать.</p>${specs([['Модель','LEAD 110'],['Объём по документу','108 см³'],['Двигатель','4-тактный · PGM-FI'],['Охлаждение','Жидкостное'],['Материалы',`${articles.length} подробных тем`]])}<button class="action-button" data-article="oil">Начать с замены масла<span aria-hidden="true">↗</span></button><h3>Быстрый доступ</h3><div class="detail-links">${['headlight','battery','fuses','seat'].map(id=>`<button class="detail-link" data-select="${id}">${byId.get(id).title}<span aria-hidden="true">↗</span></button>`).join('')}</div><div class="notice">Модель схематичная. Данные NHX110 и позиции, подтверждённые для VN, отмечены отдельно.</div><button class="detail-source" data-identity>О модификации и точности справочника ↗</button>`;return;}
 const a=byId.get(activeArticle);const related=[...(a.related||[])];
 panel.innerHTML=`<div class="detail-kicker"><span>${a.category.toUpperCase()}</span><span>${String(articles.indexOf(a)+1).padStart(2,'0')} / ${articles.length}</span></div><h2>${a.title}</h2><p class="detail-description">${a.summary}</p>${specs((a.specs||[['Справочник','Таблица и источники'],['Версия','LEAD 110 / 2009']]).slice(0,5))}${openButton(a.id)}${a.id==='headlight'?`<button class="outline-button lamp-demo" id="lampDemo" aria-pressed="${!!viewer?.isLightOn()}">${viewer?.isLightOn()?'Выключить':'Включить'} фару на модели</button>`:''}<button class="action-button" data-article="${a.id}">Инструкция и детали<span aria-hidden="true">↗</span></button><h3>Рядом с этим узлом</h3><div class="detail-links">${related.map(id=>`<button class="detail-link" data-select="${id}">${byId.get(id).title}<span aria-hidden="true">↗</span></button>`).join('')}</div><div class="notice">${a.warning||'Спецификация VN подтверждена каталогом. Процедуру NHX110 сверяй с креплениями твоего байка.'}</div><a class="detail-source" href="${a.sources[0].url}" target="_blank" rel="noopener noreferrer">${a.sources[0].label} ↗</a>`;
}
function selectSystem(id){const s=systems.find(x=>x.id===id);if(!s)return;activeSystem=id;activeArticle=s.article;renderSystems();renderDetail();viewer?.select(activeSystem,activeArticle);}
function selectArticle(id,{scroll=false}={}){const a=byId.get(id);if(!a)return;activeArticle=id;activeSystem=a.system;renderSystems();renderDetail();viewer?.select(activeSystem,id);if(scroll)$('#viewer').scrollIntoView({behavior:'smooth',block:'start'});}
function syncOpenButtons(){for(const btn of $$('[data-open]')){btn.disabled=!viewer;const part=btn.dataset.open,isOpen=viewer?.isOpen(part);btn.classList.toggle('is-open',isOpen);btn.setAttribute('aria-pressed',String(!!isOpen));const entry=opening[part];const title=part==='battery'?(isOpen?'Вернуть переднюю панель':'Доступ к аккумулятору'):part==='engine'?(isOpen?'Собрать кузов':'Доступ к мотору'):entry[isOpen?2:1];btn.childNodes.forEach(n=>{if(n.nodeType===Node.TEXT_NODE)n.textContent=title;});}}
function togglePart(part){if(!viewer){toast('3D недоступно. Инструкция по доступу есть в справочнике.');showArticle(part);return;}const on=viewer.toggle(part);const a=byId.get(part);if(a)selectArticle(part);syncOpenButtons();toast(`${opening[part][on?1:2]} · ${on?'вид изнутри':'собрано'}`);}
function renderFilters(){$('#filters').innerHTML=categories.map(c=>`<button class="filter-button ${filter===c?'active':''}" data-filter="${c}" aria-pressed="${filter===c}">${c}<span>${c==='Все узлы'?articles.length:articles.filter(a=>a.category===c).length}</span></button>`).join('');}
const normalize=t=>t.toLowerCase().replaceAll('ё','е');
function renderCards(){const q=normalize(search.trim());const list=articles.filter(a=>(filter==='Все узлы'||a.category===filter)&&(!q||normalize([a.title,a.summary,a.lead,JSON.stringify(a.specs||[]),JSON.stringify(a.table||{}),...(a.steps||[])].join(' ')).includes(q)));$('#articleGrid').innerHTML=list.map(a=>`<button class="article-card" data-article="${a.id}"><span class="card-top">${icon(a.icon)}<span>${a.category.toUpperCase()}</span></span><h3>${a.title}</h3><p>${a.summary}</p><span class="card-arrow" aria-hidden="true">↗</span></button>`).join('');$('#emptyState').hidden=list.length!==0;}
function openDialog(content){dialogTrigger=document.activeElement;$('#dialogBody').innerHTML=content;if(!$('#infoDialog').open)$('#infoDialog').showModal();$('#infoDialog').scrollTop=0;$('#closeDialog').focus();}
function showArticle(id,{historyEntry=true}={}){const a=byId.get(id);if(!a)return;selectArticle(id);openDialog(`<div class="dialog"><div class="dialog-kicker">LEAD / 09 · ${a.category.toUpperCase()}</div><h2 id="dialogTitle">${a.title}</h2><p class="dialog-lead">${a.lead}</p>${a.specs?specs(a.specs):''}${a.table?`<h3>Спецификации</h3>${table(a.table)}`:''}${a.steps?`<h3>Порядок действий</h3><ol class="dialog-steps">${a.steps.map(s=>`<li>${s}</li>`).join('')}</ol>`:''}${a.warning?`<div class="notice">${a.warning}</div>`:''}${opening[id]?`<h3>Посмотреть расположение</h3><button class="outline-button" data-show-part="${id}">Открыть на 3D-модели ↗</button>`:''}<h3>Первоисточники</h3>${a.sources.map(s=>`<a class="source-item" href="${s.url}" target="_blank" rel="noopener noreferrer"><strong>${s.label} ↗</strong><span>Откроется в новой вкладке</span></a>`).join('')}${a.related?.length?`<h3>Связанные темы</h3><div class="related">${a.related.map(x=>`<button data-article="${x}">${byId.get(x).title} ↗</button>`).join('')}</div>`:''}</div>`);if(historyEntry)history.pushState({article:id},'',`#guide/${id}`);}
function showSources(){openDialog(`<div class="dialog"><div class="dialog-kicker">ПРОВЕРЯЕМАЯ БАЗА</div><h2 id="dialogTitle">Откуда информация.</h2><p class="dialog-lead">Числа и процедуры взяты из заводского сервисного руководства Honda. Для вьетнамской версии дополнительно проверены каталожные позиции. Это не официальный сайт Honda.</p><a class="source-item" href="${manual()}" target="_blank" rel="noopener noreferrer"><strong>Honda LEAD 110 / NHX110 Service Manual, 2009 ↗</strong><span>431 страница, выпуск Honda: ноябрь 2008. Полный ремонтный мануал на зеркале ManualsLib. Основной источник процедур; не отдельный мануал Honda Vietnam.</span></a><a class="source-item" href="https://www.easymanua.ls/honda/lead-110-2009/manual" target="_blank" rel="noopener noreferrer"><strong>Второе зеркало заводского руководства ↗</strong><span>Easymanual: те же номера страниц для сверки при недоступности основного зеркала.</span></a><a class="source-item" href="${manual(421)}" target="_blank" rel="noopener noreferrer"><strong>Полная электрическая схема · 22-2 ↗</strong><span>Фабричная схема NHX110. Соответствие жгуту VN надо проверять.</span></a><a class="source-item" href="${manual(83)}" target="_blank" rel="noopener noreferrer"><strong>Заводская таблица ТО · 4-4 ↗</strong><span>Таблица NHX110 визуально сверена с оригинальной страницей Honda. Отдельный регламент Honda Vietnam 2009 не найден.</span></a><a class="source-item" href="https://xemay.net/so-do-phu-tung-pdf/65009/" target="_blank" rel="noopener noreferrer"><strong>Каталог деталей Honda Lead 110, VN, 01/2009–03/2013 ↗</strong><span>Дилерское зеркало, не официальный домен Honda. F1 — фара; F2 — приборка; F18 — фильтр; F23/F25 — задний свет; F26 — проводка. Ссылки на конкретные группы есть в карточках.</span></a><a class="source-item" href="https://global.honda/jp/news/2009/2090119-lead.html" target="_blank" rel="noopener noreferrer"><strong>Официальный архив Honda · Lead 2009, Japan ↗</strong><span>Подтверждает поколение и внешний вид. Японские 107 см³ и спецификации JF19 не объявлены характеристиками вьетнамского экземпляра.</span></a><div class="notice">Проверено 11 ноября 2026. Не найдены: официальный мануал Honda Vietnam именно 2009, карта назначения предохранителей VN, точная ёмкость штатной VN батареи и полная раскладка ламп VN приборки. Эти позиции отмечены в карточках.</div></div>`);}
function showIdentity(){openDialog(`<div class="dialog"><div class="dialog-kicker">ТВОЯ МОДИФИКАЦИЯ</div><h2 id="dialogTitle">Lead 110. Вьетнам.</h2><p class="dialog-lead">По предоставленному регистрационному документу: Honda, 108 см³, первая регистрация в 2009 году во Вьетнаме. Это согласуется с первым поколением Lead 110, но документ не подтверждает японскую маркировку JF19 и точный код модели.</p>${specs([['Цвет модели','Белый — по твоему запросу'],['Персональные данные','Не добавлены в сайт'],['Японская JF19','Не подтверждена для этого байка'],['3D','Самостоятельная low-poly схема']])}<h3>Как читать карточки</h3><p class="dialog-lead">«VN каталог» — позиция найдена в каталоге вьетнамского Lead 110 01/2009–03/2013. «NHX110» — значение или процедура из заводского сервисного мануала 2009, которые нужно сверить с твоим байком.</p><div class="notice">Для окончательной привязки расходников нужны код модели/двигателя с заводской маркировки, фото наклейки давлений и маркировка установленной батареи. По регистрационной карточке нельзя гарантировать все детали комплектации.</div><h3>Модель и разборка</h3><p class="dialog-lead">Сиденье, передняя панель, бардачок, подседельная ванна и боковые детали открываются для изучения устройства. Это учебная схема: она не воспроизводит все крепления, размеры и порядок снятия. Пошаговые процедуры и заводские рисунки доступны в карточках.</p></div>`);}
function closeDialog(){if($('#infoDialog').open)$('#infoDialog').close();}
$('#closeDialog').onclick=closeDialog;
$('#infoDialog').addEventListener('click',e=>{if(e.target===$('#infoDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
$('#infoDialog').addEventListener('close',()=>{if(location.hash.startsWith('#guide/'))history.replaceState(null,'',location.pathname+location.search);if(dialogTrigger?.isConnected)dialogTrigger.focus();});
window.addEventListener('popstate',()=>{const id=location.hash.startsWith('#guide/')?location.hash.slice(7):null;if(id&&byId.has(id))showArticle(id,{historyEntry:false});else closeDialog();});
document.addEventListener('click',e=>{
 const btn=e.target.closest('button');if(!btn)return;
 if(btn.dataset.system){selectSystem(btn.dataset.system);return;}
 if(btn.dataset.article){showArticle(btn.dataset.article);return;}
 if(btn.dataset.select){selectArticle(btn.dataset.select);return;}
 if(btn.dataset.filter){filter=btn.dataset.filter;renderFilters();renderCards();return;}
 if(btn.dataset.open){togglePart(btn.dataset.open);return;}
 if(btn.dataset.togglePart){togglePart(btn.dataset.togglePart);return;}
 if(btn.dataset.showPart){const part=btn.dataset.showPart;closeDialog();selectArticle(part,{scroll:true});if(!viewer?.isOpen(part))togglePart(part);return;}
 if(btn.hasAttribute('data-identity'))showIdentity();
 if(btn.id==='lampDemo'){if(!viewer){toast('3D недоступно');return;}const on=viewer.toggleLights();btn.textContent=on?'Выключить фару на модели':'Включить фару на модели';btn.setAttribute('aria-pressed',String(on));}
});
$('#sourcesButton').onclick=showSources;$('#allSources').onclick=showSources;$('#identityButton').onclick=showIdentity;
$('#searchInput').addEventListener('input',e=>{search=e.target.value;renderCards();});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(e.target.tagName)&&!$('#infoDialog').open){e.preventDefault();$('#searchInput').focus();$('#catalog').scrollIntoView({behavior:'smooth'});}});
$$('[data-nav]').forEach(btn=>{btn.onclick=()=>{$$('[data-nav]').forEach(x=>x.classList.toggle('active',x===btn));const target=btn.dataset.nav==='explore'?$('.intro'):$(`#${btn.dataset.nav}`);target.scrollIntoView({behavior:'smooth'});};});
$('#rotateLeft').onclick=()=>viewer?.orbit(-.3);$('#rotateRight').onclick=()=>viewer?.orbit(.3);$('#zoomIn').onclick=()=>viewer?.zoom(.9);$('#zoomOut').onclick=()=>viewer?.zoom(1.1);$('#resetView').onclick=()=>viewer?.reset();
$('#labelsToggle').onclick=()=>{const state=$('#labelsToggle').getAttribute('aria-pressed')!=='true';$('#labelsToggle').setAttribute('aria-pressed',String(state));$('#labelsToggle .switch').classList.toggle('on',state);viewer?.setLabels(state);};
const storageKey='lead09-checklist-v1';let checked={};try{checked=JSON.parse(localStorage.getItem(storageKey)||'{}');if(!checked||typeof checked!=='object')checked={};}catch(e){console.warn('Checklist storage unavailable:',e.name);}
function renderChecklist(){$('#checklist').innerHTML=checks.map(c=>`<label class="check-item"><input type="checkbox" data-check="${c.id}" ${checked[c.id]?'checked':''}><span><strong>${c.title}</strong><small>${c.description}</small></span></label>`).join('');}
function saveChecks(){try{localStorage.setItem(storageKey,JSON.stringify(checked));}catch(e){console.warn('Cannot persist checklist:',e.name);toast('Браузер не разрешил сохранение. Отметки останутся до перезагрузки.');}}
$('#checklist').addEventListener('change',e=>{if(!e.target.dataset.check)return;checked[e.target.dataset.check]=e.target.checked;saveChecks();});
$('#resetChecklist').onclick=()=>{checked={};saveChecks();renderChecklist();toast('Проверки сброшены для следующей поездки');};
renderSystems();renderDetail();renderFilters();renderCards();renderChecklist();syncOpenButtons();
try{const {createBikeViewer}=await import('./model.js');viewer=await createBikeViewer(id=>{selectArticle(id);if(innerWidth<650)toast(`${byId.get(id)?.title||'Узел'} — информация под моделью`);});viewer.select(activeSystem,activeArticle);syncOpenButtons();renderDetail();window.leadGarage={diagnostics:()=>viewer.diagnostics()};}
catch(error){console.error('3D initialization failed:',error);$('#loading').innerHTML='<div class="fallback"><strong>Не удалось запустить 3D</strong><p>Включи WebGL в браузере или открой сайт в актуальном Chrome/Edge. Все инструкции доступны в списке узлов и справочнике ниже.</p><button class="outline-button" id="reload3d">Повторить загрузку</button></div>';$('#loading').hidden=false;$('#reload3d').onclick=()=>location.reload();}
const initial=location.hash.startsWith('#guide/')?location.hash.slice(7):null;if(initial&&byId.has(initial))showArticle(initial,{historyEntry:false});
